from datetime import datetime
from hashlib import sha256
from io import BytesIO
from pathlib import Path
import gzip
import json

import numpy as np
import pandas as pd
from pandas.tseries.holiday import (
    AbstractHolidayCalendar,
    GoodFriday,
    Holiday,
    USLaborDay,
    USMartinLutherKingJr,
    USMemorialDay,
    USPresidentsDay,
    USThanksgivingDay,
    nearest_workday,
    sunday_to_monday,
)
from scipy.optimize import brentq, minimize
import yaml


ROOT = Path(__file__).resolve().parent


class USMarketHolidays(AbstractHolidayCalendar):
    rules = [
        Holiday("New Year's Day", month=1, day=1, observance=sunday_to_monday),
        USMartinLutherKingJr,
        USPresidentsDay,
        GoodFriday,
        USMemorialDay,
        Holiday("Juneteenth", month=6, day=19, start_date="2022-01-01", observance=nearest_workday),
        Holiday("Independence Day", month=7, day=4, observance=nearest_workday),
        USLaborDay,
        USThanksgivingDay,
        Holiday("Christmas Day", month=12, day=25, observance=nearest_workday),
    ]


def check_sessions(dates, start, end):
    holidays = USMarketHolidays().holidays(start, end)
    # Full-session special closures in the backtest's warm-up and evaluation window.
    mourning_closures = pd.to_datetime(["2018-12-05", "2025-01-09"])
    expected = pd.bdate_range(start, end).difference(holidays.union(mourning_closures))
    missing = expected.difference(dates)
    extra = dates.difference(expected)
    if len(missing) or len(extra):
        raise RuntimeError(
            f"Yahoo Finance calendar mismatch: {len(missing)} missing ({missing[:5].strftime('%Y-%m-%d').tolist()}), "
            f"{len(extra)} unexpected ({extra[:5].strftime('%Y-%m-%d').tolist()})"
        )


def load_config(config_path=None):
    path = Path(config_path) if config_path else (ROOT / "config.yaml")
    with open(path, "rb") as source:
        return yaml.safe_load(source)


def load_prices(tickers, start, end, settings, config_path="config.yaml"):
    data = settings.get("data") or {}
    blob = data.get("market_snapshot_gzip")
    expected_digest = data.get("market_snapshot_sha256")
    if not isinstance(blob, (bytes, bytearray)) or not expected_digest:
        raise ValueError("config.data must carry market_snapshot_gzip and market_snapshot_sha256")
    snapshot = gzip.decompress(bytes(blob))
    digest = sha256(snapshot).hexdigest()
    if digest != expected_digest:
        raise ValueError(
            f"SHA-256 mismatch for the market snapshot in {Path(config_path).name}: {digest}."
        )
    header, sep, body = snapshot.partition(b"\n")
    if not sep:
        raise ValueError("Missing cache timestamp")
    fetched_at = header.decode("utf-8").strip()
    datetime.fromisoformat(fetched_at)
    input_digest = sha256(body).hexdigest()
    with BytesIO(snapshot) as source:
        source.readline()
        prices = pd.read_csv(source, index_col=0, parse_dates=True)
    prices = prices.reindex(columns=tickers)
    if (prices.empty or list(prices.columns) != tickers or not isinstance(prices.index, pd.DatetimeIndex)
            or not prices.index.is_unique or not prices.index.is_monotonic_increasing):
        raise RuntimeError("Unexpected Yahoo Finance price layout")
    check_sessions(prices.index, start, end)
    bad_prices = ~np.isfinite(prices) | (prices <= 0)
    if bad_prices.to_numpy().any():
        missing = bad_prices.sum()
        raise RuntimeError(f"Missing or invalid adjusted closes: {missing[missing > 0].to_dict()}")
    provenance = {
        "path": Path(config_path).name,
        "key": "data.market_snapshot_gzip",
        "sha256": digest,
    }
    print(
        "Data source: yfinance auto_adjust snapshot embedded in config under data.market_snapshot_gzip "
        f"(decompressed sha256 {digest}); the script does not call yfinance or read data_cache."
    )
    print(f"Input SHA-256: {input_digest}")
    print(f"DATA_SHA256: {digest}")
    print(f"MARKET_DATA_SNAPSHOT: {json.dumps(provenance, allow_nan=False)}")
    return prices, fetched_at


def robust_weights(losses, confidence, downside_weight, threshold):
    # Work in percentage points to keep the numerical objective well scaled.
    losses = 100 * losses
    threshold *= 100
    mean_loss = losses.mean(axis=0)
    covariance = np.cov(losses, rowvar=False)
    tail = 1 - confidence
    upper_slope = 1 + downside_weight
    midpoint = (1 + upper_slope) / 2
    radius_squared = midpoint**2 - tail * upper_slope
    size = mean_loss.size
    equal_weights = np.full(size, 1 / size)

    def objective(weights):
        mean = weights @ mean_loss
        projected = covariance @ weights
        sigma = np.sqrt(max(weights @ projected, 0.0))
        gap = mean - threshold
        if sigma == 0:
            slope = upper_slope if gap > 0 else 1.0
            return mean + downside_weight * max(gap, 0.0), slope * mean_loss

        # Lemma 3.1, equations (3.5)–(3.6), scaled for model (4.3).
        # The two positive tail slopes are 1 and upper_slope. Their probability-
        # weighted sum lies in [tail, tail * upper_slope]. The scalar maximizer
        # gives the same three regimes as Theorem 3.1(b).
        tail_slope = midpoint + np.sqrt(radius_squared) * gap / np.hypot(gap, sigma)
        tail_slope = np.clip(tail_slope, tail, tail * upper_slope)
        slope_std = np.sqrt(radius_squared - (tail_slope - midpoint)**2)
        value = threshold + (gap * tail_slope + sigma * slope_std) / tail
        gradient = (tail_slope * mean_loss + slope_std * projected / sigma) / tail
        return value, gradient

    optimum = minimize(
        objective,
        equal_weights,
        jac=True,
        method="SLSQP",
        bounds=[(0.0, 1.0)] * size,
        constraints={"type": "eq", "fun": lambda w: w.sum() - 1, "jac": lambda w: np.ones(size)},
        options={"ftol": 1e-10, "maxiter": 200},
    )
    if not optimum.success or not np.isfinite(optimum.x).all():
        raise RuntimeError(f"Risk optimization failed: {optimum.message}")
    weights = optimum.x.clip(min=0.0)
    return weights / weights.sum()


def size_changes(positions, cash, previous_close, target, cost_rate, cash_buffer):
    previous_value = cash + positions @ previous_close
    current_exposures = positions * previous_close

    def remaining_value(risky_value):
        # Estimate both fees and the cash reserve using the sizing close.
        fees = cost_rate * np.abs(risky_value * target - current_exposures).sum()
        return risky_value / (1 - cash_buffer) + fees - previous_value

    risky_value = brentq(remaining_value, 0.0, previous_value)
    changes = risky_value * target / previous_close - positions
    # Ignore numerical dust at sizing, before the fill close is available.
    changes[np.abs(changes) * previous_close <= 1e-8 * previous_value] = 0.0
    changes.setflags(write=False)
    return changes, previous_value


def settle_fill(cash, share_changes, fill_prices, cost_rate, fill_date):
    traded_value = np.abs(share_changes) @ fill_prices
    fees = traded_value * cost_rate
    cash_after_fill = cash - (share_changes @ fill_prices + fees)
    if not (np.isfinite(traded_value) and np.isfinite(cash_after_fill)):
        raise RuntimeError(f"{fill_date:%Y-%m-%d}: non-finite fill amount or cash balance")
    if cash_after_fill < 0:
        raise RuntimeError(
            f"{fill_date:%Y-%m-%d}: predetermined quantities exceed available cash "
            f"by {-cash_after_fill:.8g} per unit of starting capital"
        )
    return cash_after_fill, traded_value


def simulate(prices, first, lookback, lag, cost_rate, cash_buffer, model=None):
    asset_prices = prices.to_numpy()
    asset_returns = prices.pct_change(fill_method=None).to_numpy()
    size = asset_prices.shape[1]
    positions = np.zeros(size)
    cash = 1.0
    equal_weights = np.full(size, 1 / size)
    daily_results = []

    for fill in range(first, len(prices)):
        signal = fill - lag
        target = equal_weights
        if model is not None:
            losses = -asset_returns[signal - lookback + 1:signal + 1]
            target = robust_weights(losses, *model)

        previous_close = asset_prices[fill - 1]
        share_changes, previous_value = size_changes(positions, cash, previous_close, target, cost_rate, cash_buffer)
        next_positions = positions + share_changes
        next_positions.setflags(write=False)

        # Settle the predetermined changes before committing either state update.
        fill_prices = asset_prices[fill]
        cash_after_fill, traded_value = settle_fill(cash, share_changes, fill_prices, cost_rate, prices.index[fill])
        pre_fill_value = cash + positions @ fill_prices
        positions = next_positions
        cash = cash_after_fill
        value = cash + positions @ fill_prices
        daily_results.append((
            value / previous_value - 1,
            traded_value / pre_fill_value,
            np.count_nonzero(share_changes),
            cash / value,
        ))

    return pd.DataFrame(
        daily_results, index=prices.index[first:], columns=["return", "turnover", "n_trades", "cash_weight"]
    )


def metrics(rows, risk_free, annualization):
    daily = rows["return"]
    excess = daily - risk_free.loc[rows.index]
    growth = np.r_[1.0, (1 + daily).cumprod().to_numpy()]
    vol = daily.std(ddof=1)
    excess_vol = excess.std(ddof=1)
    root_year = np.sqrt(annualization)
    return {
        "cagr": float(growth[-1]**(annualization / len(rows)) - 1),
        "ann_vol": float(vol * root_year),
        "sharpe": float(daily.mean() / vol * root_year) if vol > 0 else None,
        "sharpe_excess": float(excess.mean() / excess_vol * root_year) if excess_vol > 0 else None,
        "max_drawdown": float(np.min(growth / np.maximum.accumulate(growth) - 1)),
        "total_return": float(growth[-1] - 1),
        "turnover": float(rows["turnover"].mean() * annualization),
        "n_trades": int(rows["n_trades"].sum()),
    }


def realized_loss_cvar(rows, confidence):
    losses = np.sort(-rows["return"].to_numpy())[::-1]
    tail_count = len(losses) * (1 - confidence)
    whole = int(tail_count)
    partial_loss = (tail_count - whole) * losses[whole:whole + 1].sum()
    return float((losses[:whole].sum() + partial_loss) / tail_count)


def main():
    config = load_config(str(ROOT / "config.yaml"))

    universe = config["universe"]
    risk_free_ticker = config["risk_free_ticker"]
    tickers = [*universe, risk_free_ticker]
    data_start, start, split, end = (pd.Timestamp(config[key]) for key in ("data_start", "start", "is_end", "end"))
    if len(universe) < 2 or len(set(tickers)) != len(tickers):
        raise ValueError("Use at least two distinct universe symbols and a separate risk-free symbol")
    if risk_free_ticker != "BIL":
        raise ValueError("The risk-free proxy must be BIL adjusted returns")
    if not data_start < start <= split < end:
        raise ValueError("Invalid warm-up, evaluation or split dates")
    lag = config["signal_lag_sessions"]
    lookback = config["lookback_sessions"]
    annualization = config["annualization_sessions"]
    if any(type(value) is not int for value in (lag, lookback, annualization)):
        raise ValueError("Lag, lookback and annualization must be integer session counts")
    if lag < 1 or lookback < 2 or annualization < 1:
        raise ValueError("Invalid lag, lookback or annualization session counts")
    confidence = config["cvar_confidence"]
    downside_weight = config["downside_weight"]
    threshold = config["loss_threshold"]
    if not (0 < confidence < 1 and 0 < downside_weight < np.inf and np.isfinite(threshold)):
        raise ValueError("Invalid reward-penalty model parameters")
    cost_bps, slippage_bps = config["cost_bps"], config["slippage_bps"]
    cost_rate = (cost_bps + slippage_bps) / 10_000
    if not (cost_bps >= 0 and slippage_bps >= 0 and cost_rate < 1):
        raise ValueError("Invalid cost or slippage")
    cash_buffer = config["cash_buffer_bps"] / 10_000
    if not 0 < cash_buffer < 1:
        raise ValueError("Invalid cash buffer")

    prices, fetched_at = load_prices(
        tickers, data_start, end, config, str(ROOT / "config.yaml"),
    )
    print(f"DATA_FETCHED_AT: {fetched_at}")
    print("PRICE_ADJUSTMENT: yfinance auto_adjust=True total-return adjusted closes, fractional adjusted units")
    first = prices.index.searchsorted(start)
    boundary = prices.index.searchsorted(split, side="right")
    if first - lag - lookback + 1 < 1:
        raise ValueError("Insufficient warm-up prices for the first evaluation session")
    if min(boundary - first, len(prices) - boundary) < 2:
        raise ValueError("Both IS and OOS need at least two evaluation sessions")

    periods = {"is": slice(None, boundary - first), "oos": slice(boundary - first, None), "full": slice(None)}
    risk_free = prices[risk_free_ticker].pct_change(fill_method=None)
    simulation_inputs = (prices[universe], first, lookback, lag, cost_rate, cash_buffer)
    model = (confidence, downside_weight, threshold)
    print("PARAM_COMBOS_TRIED: 1")
    daily_results = simulate(*simulation_inputs, model=model)
    benchmark = simulate(*simulation_inputs)
    plain_cvar = simulate(*simulation_inputs, model=(confidence, 0.0, threshold))
    summaries = {}
    tail_losses = {}
    min_cash_weights = {}
    for name, rows in (("strategy", daily_results), ("benchmark", benchmark), ("plain_cvar", plain_cvar)):
        summaries[name] = {
            period: metrics(rows.iloc[window], risk_free, annualization) for period, window in periods.items()
        }
        tail_losses[name] = {
            period: realized_loss_cvar(rows.iloc[window], confidence) for period, window in periods.items()
        }
        min_cash_weights[name] = float(rows["cash_weight"].min())

    report = {
        "strategy": config["strategy"],
        "data_range": {"start": str(daily_results.index[0].date()), "end": str(daily_results.index[-1].date())},
        **summaries["strategy"],
        "benchmark": summaries["benchmark"]["full"],
    }
    for period in periods:
        print(f"{period.upper()}: {json.dumps(report[period], allow_nan=False)}")
    for period in ("is", "oos"):
        print(f"BENCHMARK {period.upper()}: {json.dumps(summaries['benchmark'][period], allow_nan=False)}")
    print(f"BENCHMARK (daily equal weight, full period): {json.dumps(report['benchmark'], allow_nan=False)}")
    for period in periods:
        print(f"PLAIN_WC_CVAR {period.upper()}: {json.dumps(summaries['plain_cvar'][period], allow_nan=False)}")
    print(f"REALIZED_LOSS_CVAR: {json.dumps(tail_losses, allow_nan=False)}")
    print(f"MIN_POST_FILL_CASH_WEIGHT: {json.dumps(min_cash_weights, allow_nan=False)}")
    print(f"RESULTS_JSON: {json.dumps(report, allow_nan=False)}")


if __name__ == "__main__":
    main()
